import hashlib, json
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

class MailLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        href = dict(attrs).get('href') or ''
        if tag == 'a' and href.lower().startswith('mailto:'):
            self.current = (urlsplit(href), [])

    def handle_data(self, text):
        if self.current is not None:
            self.current[1].append(text)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current is not None:
            target, label = self.current
            query = parse_qs(target.query, keep_blank_values=True)
            self.links.append({'label': ' '.join(''.join(label).split()), 'subject': query.get('subject', []), 'body': query.get('body', []), 'recipient_present': bool(target.path)})
            self.current = None

root = Path('products/distribution/invoice-live-quote-rehearsal')
source = root / 'served-homepage.html'
report = {'source': str(source), 'scope': 'Static decoding of public inquiry links. No email client, private cycle, recipient delivery, order or payment was tested.'}
if source.is_file():
    raw = source.read_bytes()
    parser = MailLinks()
    parser.feed(raw.decode('utf-8'))
    report.update(sha256=hashlib.sha256(raw).hexdigest(), mailto_links=parser.links, distinct_nonempty_subjects=sorted({subject for link in parser.links for subject in link['subject'] if subject.strip()}))
else:
    report['limitation'] = 'The served homepage capture was unavailable to this execution.'
root.mkdir(parents=True, exist_ok=True)
output = root / 'served-link-controls.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
